def allowed(role, actor_tenant, actor_id, item):
    return role == "admin" or (actor_tenant == item["tenant"] and actor_id == item["owner"])

def archive(records, key, role, tenant, actor_id):
    item = records[key]
    item["state"] = "archived"
    if not allowed(role, tenant, actor_id, item):
        raise PermissionError("denied")
    return item

