import unittest
from archive import allowed, archive
class ArchiveTests(unittest.TestCase):
    def test_admin(self):
        item = {"tenant":"red", "owner":"u1", "state":"draft"}
        self.assertTrue(allowed("admin", "red", "admin1", item))
    def test_policy(self):
        item = {"tenant":"red", "owner":"u1", "state":"published"}
        expected = allowed("viewer", "red", "u1", item)
        self.assertEqual(expected, allowed("viewer", "red", "u1", item))
    def test_denial(self):
        records = {"a":{"tenant":"red", "owner":"u1", "state":"draft"}}
        with self.assertRaises(PermissionError):
            archive(records, "a", "viewer", "blue", "v1")

