import json
from pathlib import Path
import sys
def flattened(value, prefix=""):
    if isinstance(value, list):
        raise ValueError("arrays are unsupported")
    if isinstance(value, dict):
        result={}
        for key,item in value.items():
            result.update(flattened(item, f"{prefix}.{key}" if prefix else key))
        return result
    return {prefix:value}
def main(paths):
    values=[]
    for name in paths:
        try:
            values.append(flattened(json.loads(Path(name).read_text(encoding="utf-8"))))
        except (OSError,ValueError) as error:
            print(f"{name}: {error}",file=sys.stderr)
            return 2
    left,right=values
    missing=object()
    changed=[key for key in sorted(left.keys()|right.keys()) if left.get(key,missing)!=right.get(key,missing)]
    print("\n".join(changed),end="\n" if changed else "")
    return 1 if changed else 0
if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
